struct Dir;
using Node = std::variant<File, std::unique_ptr<Dir>>;   // closed node set
struct Dir { std::vector<Node> children; };
long size(const Node& n) {
    return std::visit(overloaded{
        [](const File& f) { return f.bytes; },
        [](const std::unique_ptr<Dir>& d) {
            long s = 0; for (auto& c : d->children) s += size(c); return s; }
    }, n);
}

